{
  "approved_angle": {
    "title": "I want to know what made a couple book, as well as what they loved afterward",
    "core_perspective": "I want to understand what a couple was weighing when they chose your business. Their review can tell us what they loved about the experience. Asking about the booking decision can give us different information to consider when we write your ads."
  },
  "sharpened_point": null,
  "strategic_purpose": {
    "pillar": "ATTRACT",
    "content_type": "founder_forward",
    "why_now": "Show prospective clients a specific question behind WIA's advertising strategy. The distinction between enjoying the wedding experience and deciding to book gives owners with strong reviews a useful new perspective, without repeating the recent UVP training or introducing an offer."
  },
  "audience": {
    "who": "Wedding business owners with strong reviews who already invest in marketing and want their ads to reflect why best-fit couples choose them.",
    "reason_to_care": "They may reasonably think their reviews already explain what couples value. This piece shows how asking about the earlier booking decision can add another source of information for their advertising."
  },
  "intended_shift": {
    "understand": "Reviews and questions about the booking decision can reveal different parts of a couple's experience.",
    "believe": "WIA wants to understand the couple's reasons for choosing, alongside the owner's account of what makes the business valuable.",
    "do": "Consider what they could learn by asking newly booked couples about their decision."
  },
  "point_of_view": "I",
  "wia_perspective": "When we’re getting to know a new ELEVATE client, we ask what research they can share about why couples choose them. Reviews are useful, and I also want to understand the choice that came before the experience those reviews describe.\n\nIn a conversation with our team about our own marketing, I suggested asking couples about that decision soon after they book. What were they considering? What helped them feel ready to choose?\n\nTheir answers can give us another source to consider when we write ads and landing pages. We can hear how the couple describes the decision, alongside what the business owner knows about the experience they deliver.",
  "supporting_example": {
    "scene": "I was talking with our team about improving WIA’s own marketing, and I brought up a question we ask new ELEVATE clients: what research can they share about why couples book them?",
    "wia_move": "I suggested asking newly booked couples about their decision and considering what we learn when we write ad copy and landing pages.",
    "client_contribution": "The couple’s own description of what they were weighing is what I want to hear, alongside what they loved about their wedding experience."
  },
  "narrative_outline": {
    "hooks": [
      {
        "style": "observation",
        "text": "When we ask about why couples book, I want to hear about the moment they chose you."
      },
      {
        "style": "question",
        "text": "What convinced a couple to book before they had a wedding experience to review?"
      },
      {
        "style": "contrarian_belief",
        "text": "There’s more to a couple’s decision than what they loved afterward."
      }
    ],
    "problems_desires_symptoms": [
      "Owners want advertising that reflects what their best-fit couples value.",
      "Strong reviews may feel like a complete explanation of why couples choose the business.",
      "The owner wants to communicate the reasons to book in language couples recognize."
    ],
    "main_point": "Separate feedback about the delivered experience from the couple's account of choosing the business. Show why WIA wants both.",
    "transformation": "The owner sees newly booked couples as another source of information to consider in ad messaging, without assuming what their answers will be.",
    "cta": "Understanding the choice gives us another part of the couple’s story to consider."
  },
  "format_plan": {
    "reels": [
      {
        "job": "Introduce the distinction through Whitney's real internal-team conversation. Keep it to one founder-led Reel.",
        "cover_text": "The decision before the review",
        "spoken_opening": "What helped your best-fit couples choose you while their wedding was still ahead of them?",
        "beats": [
          "Recognize reviews as useful evidence of the experience a business delivers.",
          "Recount Whitney's internal conversation about WIA's marketing and the research question asked during ELEVATE onboarding.",
          "Describe her suggestion to ask newly booked couples what they were weighing.",
          "Connect those answers to information WIA can consider in ad copy and landing pages.",
          "End on the value of hearing the couple's account of choosing, with no offer or explicit ask."
        ],
        "read_time_seconds": 60,
        "source": "new_script",
        "evidence_ids": [
          "ev_fd7910749f6b4ea23a88cb58",
          "ev_63129cd508558d77a01ff68b",
          "ev_98fb46a1eff79bc1765f98e8",
          "ev_2a47c48f852edd53262d1327",
          "ev_cc67e45e49c59eb19d6fc178",
          "ev_4cf6a239636595d938c9fc24",
          "ev_da4c80edaa2541df2a5af54b"
        ]
      }
    ],
    "carousel": {
      "job": "Make the distinction useful to an owner: value the reviews, identify the earlier decision, and offer questions WIA recommends asking.",
      "slides": [
        {
          "number": 1,
          "job": "Open on the earlier moment in the couple's story.",
          "text": "A couple has a story to tell before the wedding happens.\n\nThey’ve already considered their options and chosen your business. I want to understand what mattered during that decision, alongside what they’ll love about the experience afterward.",
          "evidence_ids": [
            "ev_63129cd508558d77a01ff68b",
            "ev_2a47c48f852edd53262d1327"
          ]
        },
        {
          "number": 2,
          "job": "Establish the value of reviews without treating them as the whole story.",
          "text": "Your reviews give us useful information.\n\nThey can tell us what couples appreciated about working with you and which parts of their wedding experience stood out. That matters when we’re getting to know your business. Asking about the booking decision gives us another question to explore.",
          "evidence_ids": [
            "ev_98fb46a1eff79bc1765f98e8",
            "ev_2a47c48f852edd53262d1327"
          ]
        },
        {
          "number": 3,
          "job": "Show the real WIA contribution.",
          "text": "This came up in a conversation with our team about WIA’s own marketing.\n\nI brought up the research we ask new ELEVATE clients to share. I wanted to hear more about why couples chose them, so I suggested asking couples about that choice soon after they book.",
          "evidence_ids": [
            "ev_fd7910749f6b4ea23a88cb58",
            "ev_63129cd508558d77a01ff68b",
            "ev_98fb46a1eff79bc1765f98e8",
            "ev_cc67e45e49c59eb19d6fc178"
          ]
        },
        {
          "number": 4,
          "job": "Give a concrete recommendation about what to ask.",
          "text": "I’d start with what they were weighing.\n\nWhat were you looking for when you began considering businesses like ours? What mattered most as you compared your options?\n\nThose questions invite the couple to describe the decision in their own words.",
          "evidence_ids": [
            "ev_63129cd508558d77a01ff68b",
            "ev_2a47c48f852edd53262d1327"
          ]
        },
        {
          "number": 5,
          "job": "Explore what helped the couple commit.",
          "text": "Then I’d ask about what helped them choose.\n\nWas there something you learned or experienced that helped you feel ready to book? What made our business feel like a good fit for your wedding?\n\nI want to leave room for their answer, rather than suggest the reason myself.",
          "evidence_ids": [
            "ev_63129cd508558d77a01ff68b",
            "ev_2a47c48f852edd53262d1327",
            "ev_f0d6efdb4ef1e0d781c7a324"
          ]
        },
        {
          "number": 6,
          "job": "Connect the recommendation to advertising work.",
          "text": "That’s information we can consider in your advertising.\n\nI suggested bringing what we learn back into ad copy and landing pages. The couple’s account can give us more to work with as we decide which reasons to choose your business to communicate, and how to describe them.",
          "evidence_ids": [
            "ev_4cf6a239636595d938c9fc24",
            "ev_da4c80edaa2541df2a5af54b"
          ]
        },
        {
          "number": 7,
          "job": "Resolve the idea without an offer or explicit ask.",
          "text": "I want to understand the choice as well as the experience.\n\nYour reviews help us learn what couples loved. Their account of booking can help us explore what mattered while they were deciding. Both are useful perspectives to bring into the conversation about your ads.",
          "evidence_ids": [
            "ev_98fb46a1eff79bc1765f98e8",
            "ev_2a47c48f852edd53262d1327",
            "ev_da4c80edaa2541df2a5af54b"
          ]
        }
      ]
    },
    "email": {
      "subject_options": [
        "The part of a couple’s story I want to hear",
        "Before the wedding, there was a choice"
      ],
      "preview": "What couples loved afterward and what helped them book are both worth understanding.",
      "opening": "Hi {{contact.first_name}},\n\nA glowing review gives you something useful to share with future couples. It also gives us information about the experience your business delivers.\n\nWhen we’re getting to know your business for advertising, I want to understand an earlier part of that couple’s story, too: what mattered while they were deciding whether to book you.",
      "argument": "During a team conversation about our own marketing, I brought up the research we ask new ELEVATE clients to share. Reviews help us hear what couples appreciated afterward. I also want to hear their account of making the choice.\n\nI suggested asking couples about that decision soon after they book. What were they looking for? What were they weighing as they considered their options? What helped them feel comfortable choosing your business?\n\nI’d leave those questions open so the couple can describe what mattered to them, rather than confirm a reason we’ve already supplied.\n\nFor us, the connection to advertising is straightforward. Their answers can give us another source to consider when we write ad copy and landing pages. We can consider what they say alongside the owner’s knowledge of the business and the experience described in its reviews.",
      "transformation": "If you have strong reviews, this adds another perspective to what you already know. You can explore the reasons couples chose you before they knew what working with you would feel like.\n\nThat’s a useful distinction when you want your advertising to reflect why your business matters to the couples you’re best suited to serve.",
      "ending": "I’m interested in the whole story: what helped them choose, and what they valued once they did.\n\nTalk soon,\nWhitney",
      "evidence_ids": [
        "ev_fd7910749f6b4ea23a88cb58",
        "ev_63129cd508558d77a01ff68b",
        "ev_98fb46a1eff79bc1765f98e8",
        "ev_2a47c48f852edd53262d1327",
        "ev_cc67e45e49c59eb19d6fc178",
        "ev_4cf6a239636595d938c9fc24",
        "ev_da4c80edaa2541df2a5af54b"
      ]
    },
    "caption": {
      "hook": "There’s useful advertising information in the moment a couple commits to your business.",
      "adds": "If you have strong reviews, you already have a valuable way to understand what couples appreciated about their wedding experience. When you want your ads to reflect why your best-fit couples choose you, I’d also ask about the decision that came before it.\n\nThis was something I brought up while talking with our team about improving WIA’s own marketing. We ask new ELEVATE clients what research they can share, and I suggested asking newly booked couples about how they made their choice.\n\nI’d want to hear what they were considering and what helped them feel ready to book. Open questions give them room to describe that in their own language.\n\nTheir answers can become another source we consider when writing ad copy and landing pages, alongside the business owner’s perspective and what its reviews tell us. That gives us more information to consider as we decide which reasons to choose the business to communicate.",
      "ending": "What they loved afterward matters. I want to hear what mattered beforehand, too.\n\nXO, Whitney"
    },
    "stories": null
  },
